css:
.turnaround-sim-container {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #e0e0e0;
  padding: 30px 20px;
  border-radius: 8px;
  max-width: 1200px;
  margin: 20px auto;
}

.turnaround-sim-header {
  text-align: center;
  margin-bottom: 30px;
  border-bottom: 3px solid #d4a574;
  padding-bottom: 20px;
}

.turnaround-sim-header h1 {
  font-size: 28px;
  font-weight: 700;
  color: #ffffff;
  margin: 0 0 10px 0;
}

.turnaround-sim-header .subtitle {
  font-size: 14px;
  color: #b0b0b0;
  margin: 0;
  font-style: italic;
}

.turnaround-sim-period-counter {
  text-align: center;
  font-size: 16px;
  color: #d4a574;
  margin-bottom: 25px;
  font-weight: 600;
}

.turnaround-sim-status-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 15px;
  margin-bottom: 30px;
}

.turnaround-sim-container .status-card {
  background: rgba(255, 255, 255, 0.05);
  border-left: 4px solid #d4a574;
  padding: 20px;
  border-radius: 4px;
  backdrop-filter: blur(10px);
}

.turnaround-sim-container .status-card h3 {
  font-size: 12px;
  color: #b0b0b0;
  margin: 0 0 10px 0;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.turnaround-sim-container .status-card .status-value {
  font-size: 24px;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 5px;
}

.turnaround-sim-container .status-card small {
  font-size: 11px;
  color: #808080;
}

.turnaround-sim-container .cash-card {
  border-left-color: #4CAF50;
}

.turnaround-sim-container .cash-card .status-value {
  color: #4CAF50;
}

.turnaround-sim-container .ebitda-card {
  border-left-color: #FF6B6B;
}

.turnaround-sim-container .ebitda-card .status-value {
  color: #FF6B6B;
}

.turnaround-sim-container .confidence-card {
  border-left-color: #FFA726;
}

.turnaround-sim-container .confidence-card .status-value {
  color: #FFA726;
}

.turnaround-sim-container .score-card {
  border-left-color: #29B6F6;
}

.turnaround-sim-container .score-card .status-value {
  color: #29B6F6;
}

.turnaround-sim-briefing {
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(212, 165, 116, 0.3);
  border-radius: 4px;
  padding: 20px;
  margin-bottom: 20px;
}

.turnaround-sim-briefing h2 {
  font-size: 18px;
  color: #d4a574;
  margin: 0 0 15px 0;
  font-weight: 600;
}

.turnaround-sim-briefing p {
  font-size: 14px;
  line-height: 1.6;
  color: #d0d0d0;
  margin: 0;
}

.turnaround-sim-event-panel {
  background: rgba(255, 107, 107, 0.15);
  border-left: 4px solid #FF6B6B;
  padding: 15px;
  margin-bottom: 20px;
  border-radius: 4px;
}

.turnaround-sim-container .event-alert {
  font-size: 14px;
}

.turnaround-sim-container .event-alert strong {
  color: #FF6B6B;
}

.turnaround-sim-container .event-alert p {
  margin: 10px 0 0 0;
  color: #e0e0e0;
}

.turnaround-sim-controls {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(212, 165, 116, 0.3);
  border-radius: 4px;
  padding: 20px;
  margin-bottom: 25px;
}

.turnaround-sim-container .control-group {
  margin-bottom: 15px;
}

.turnaround-sim-container .control-group label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: #d4a574;
  margin-bottom: 8px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.turnaround-sim-container .control-group .form-control {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(212, 165, 116, 0.5);
  color: #e0e0e0;
  padding: 10px 12px;
  border-radius: 4px;
  font-size: 14px;
}

.turnaround-sim-container .control-group .form-control:focus {
  background: rgba(0, 0, 0, 0.4);
  border-color: #d4a574;
  color: #ffffff;
  box-shadow: 0 0 0 0.2rem rgba(212, 165, 116, 0.25);
}

.turnaround-sim-container .control-group .form-control option {
  background: #1a1a2e;
  color: #e0e0e0;
}

.turnaround-sim-container .control-buttons {
  display: flex;
  gap: 10px;
  margin-top: 20px;
}

.turnaround-sim-container .control-buttons .btn {
  padding: 10px 20px;
  font-size: 14px;
  font-weight: 600;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.3s ease;
}

.turnaround-sim-container .control-buttons .btn-primary {
  background: #d4a574;
  color: #1a1a2e;
  border: none;
}

.turnaround-sim-container .control-buttons .btn-primary:hover {
  background: #e8b887;
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(212, 165, 116, 0.3);
}

.turnaround-sim-container .control-buttons .btn-secondary {
  background: rgba(212, 165, 116, 0.2);
  color: #d4a574;
  border: 1px solid #d4a574;
}

.turnaround-sim-container .control-buttons .btn-secondary:hover {
  background: rgba(212, 165, 116, 0.3);
}

.turnaround-sim-charts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 20px;
  margin-bottom: 30px;
}

.turnaround-sim-container .chart-container {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(212, 165, 116, 0.3);
  border-radius: 4px;
  padding: 20px;
}

.turnaround-sim-container .chart-container h3 {
  font-size: 14px;
  color: #d4a574;
  margin: 0 0 15px 0;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.turnaround-sim-container .chart-container canvas {
  max-width: 100%;
  height: auto;
}

.turnaround-sim-history {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(212, 165, 116, 0.3);
  border-radius: 4px;
  padding: 20px;
}

.turnaround-sim-history h3 {
  font-size: 14px;
  color: #d4a574;
  margin: 0 0 15px 0;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.turnaround-sim-history .table {
  color: #e0e0e0;
  margin: 0;
  font-size: 13px;
}

.turnaround-sim-history .table thead th {
  color: #d4a574;
  border-color: rgba(212, 165, 116, 0.3);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.turnaround-sim-history .table tbody td {
  border-color: rgba(212, 165, 116, 0.2);
  padding: 10px;
}

.turnaround-sim-history .table tbody tr:hover {
  background: rgba(212, 165, 116, 0.1);
}

@media (max-width: 768px) {
  .turnaround-sim-container {
    padding: 20px 15px;
  }

  .turnaround-sim-header h1 {
    font-size: 22px;
  }

  .turnaround-sim-status-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .turnaround-sim-charts {
    grid-template-columns: 1fr;
  }

  .turnaround-sim-container .control-buttons {
    flex-direction: column;
  }

  .turnaround-sim-container .control-buttons .btn {
    width: 100%;
  }

  .turnaround-sim-history .table {
    font-size: 12px;
  }

  .turnaround-sim-history .table tbody td {
    padding: 8px;
  }
}

@media (max-width: 480px) {
  .turnaround-sim-status-cards {
    grid-template-columns: 1fr;
  }

  .turnaround-sim-header h1 {
    font-size: 18px;
  }

  .turnaround-sim-container .status-card .status-value {
    font-size: 20px;
  }
}

