      var performance = t('perfBeginner');
      if (isInsolvent) performance = t('perfInsolvent');
      else if (score >= 75) performance = t('perfExcellent');
      else if (score >= 60) performance = t('perfGood');
      else if (score >= 45) performance = t('perfModerate');

      var insights = [];
      if (isInsolvent) {
        insights.push(t('insightInsolvent'));
      } else if (score >= 75) {
        insights.push(t('insightExcellent'));
      } else if (score >= 60) {
        insights.push(t('insightGood'));
      } else {
        insights.push(t('insightModerate'));
      }

      return {
        totalScore: score,
        performance: performance,
        insights: insights,
        liquidityScore: results.liquidityScore || 0,
        operationalScore: results.operationalScore || 0,
        stakeholderScore: results.stakeholderScore || 0,
        coherenceScore: results.coherenceScore || 0
      };
    }

    getHint(state, results) {
      if (!results) return null;
      if (state.domainState.insolvent) return window.mySimulation.t('hint_insolvent');
      if (results.cash < 5000000 && state.currentPeriod <= 2) return window.mySimulation.t('hint_low_cash');
      if (results.stakeholderScore < 25) return window.mySimulation.t('hint_low_confidence');
      if (state.currentPeriod === 1) return window.mySimulation.t('hint_r1_complete');
      if (state.currentPeriod === 2) return window.mySimulation.t('hint_r2_complete');
      if (state.currentPeriod === 3) return window.mySimulation.t('hint_r3_complete');
      if (state.currentPeriod === 4) return window.mySimulation.t('hint_r4_complete');
      return null;
    }

    getHistoryTableConfig() {
      return [
        { key: 'results.period', label: 'Round', i18nKey: 'historyRound' },
        { key: 'results.strategy', label: 'Strategy', i18nKey: 'historyStrategy' },
        { key: 'results.communication', label: 'Communication', i18nKey: 'historyCommunication' },
        { key: 'results.resource', label: 'Resource', i18nKey: 'historyResource' },
        { key: 'results.cash', label: 'Cash After', i18nKey: 'historyCash', formatter: function(v) { return '$' + (v / 1000000).toFixed(1) + 'M'; } },
        { key: 'results.turnAroundScore', label: 'Score', i18nKey: 'historyScore', formatter: function(v) { return v.toFixed(1); } }
      ];
    }

    getPresets() { return null; }

